function hash(str) {
  // simple deterministic string hash for the exercise; not cryptographic
  let h = 0;
  for (let i = 0; i < str.length; i++) h = (Math.imul(31, h) + str.charCodeAt(i)) | 0;
  return h >>> 0;
}

class HashRing {
  constructor(vnodesPerNode = 1) {
    this.vnodesPerNode = vnodesPerNode;
    this.ring = []; // sorted [{ hash, node }]
  }
  addNode(node) {
    for (let v = 0; v < this.vnodesPerNode; v++) {
      this.ring.push({ hash: hash(`${node}#${v}`), node });
    }
    this.ring.sort((a, b) => a.hash - b.hash);
  }
  removeNode(node) {
    this.ring = this.ring.filter((entry) => entry.node !== node);
  }
  getNode(key) {
    const h = hash(key);
    const entry = this.ring.find((e) => e.hash >= h) ?? this.ring[0];
    return entry.node;
  }
}

